  "language": "en",
  "source_type": "technical PDF",
  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_drain_hose",
        "name": "Drain hose",
        "description": "Hose connected to the air filter bowl fitting and routed through the base of the power supply.",
        "category": "drainage"
      },
      {
        "component_id": "comp_gas_supply_hoses",
        "name": "Gas supply hoses",
        "description": "Shorter and longer hoses connecting the air filter, solenoid valve, and plastic 90° fitting for the torch lead.",
        "category": "gas supply"
      },
      {
        "component_id": "comp_90_degree_fitting",
        "name": "Plastic 90° fitting",
        "description": "Fitting connecting the longer gas supply hose to the torch lead’s brass gas supply fitting.",
        "category": "gas supply"
      },
      {
        "component_id": "comp_air_filter",
        "name": "Air filter",
        "description": "Air filter with a bowl fitting for the drain hose and a fitting for the shorter gas supply hose.",
        "category": "air filtration"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "Valve connected to the shorter and longer gas supply hoses.",
        "category": "gas control"
      },
      {
        "component_id": "comp_torch_lead",
        "name": "Torch lead",
        "description": "Torch lead with a brass gas supply fitting inside the front panel.",
        "category": "torch assembly"
      },
      {
        "component_id": "comp_wire_group",
        "name": "Wire group",
        "description": "Replacement kit consisting of twisted pair wires between the power board and compressor-driver board, a ground clip wire, and a ground wire between the heatsink and magnetics assembly.",
        "category": "electrical wiring"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board with a J9 connector for the twisted pair wires connected to the compressor-driver board.",
        "category": "electrical"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Board with a J1 connector for the twisted pair wires connected to the power board.",
        "category": "electrical control"
      },
      {
        "component_id": "comp_ground_clip_wire",
        "name": "Ground clip wire",
        "description": "Wire connecting the center panel to the rear panel’s ground clip.",
        "category": "grounding"
      },
      {
        "component_id": "comp_ground_wire",
        "name": "Ground wire",
        "description": "Wire connecting the heatsink to the magnetics assembly.",
        "category": "grounding"
      },
      {
        "component_id": "comp_center_panel",
        "name": "Center panel",
        "description": "Panel with wire-routing notches and attachment points for ground wires.",
        "category": "structural"
      },
      {
        "component_id": "comp_rear_panel",
        "name": "Rear panel",
        "description": "Panel with a ground clip connected to the ground clip wire.",
        "category": "structural"
      },
      {
        "component_id": "comp_heatsink",
        "name": "Heatsink",
        "description": "Component to which one end of the ground wire is attached.",
        "category": "thermal management"
      },
      {
        "component_id": "comp_magnetics_assembly",
        "name": "Magnetics assembly",
        "description": "Assembly with a metal base plate to which one end of the ground wire is attached.",
        "category": "electrical"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "Cover removed and installed as part of the wire replacement procedures.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "Barrier removed and installed as part of the wire replacement procedures.",
        "category": "electrical protection"
      }
    ]
  },
  "relations": []
}
